python3 -c "
# Verify all navigation links resolve to existing files
import os, re

files = [f for f in os.listdir('.') if f.endswith('.html')]
all_links = set()
for f in files:
    with open(f) as fh:
        content = fh.read()
    # Find href links to local pages
    links = re.findall(r'href=\"([a-z\-]+\.html)\"', content)
    for link in links:
        all_links.add((f, link))

missing = []
for source, target in all_links:
    if not os.path.exists(target):
        missing.append((source, target))

if missing:
    print('BROKEN LINKS:')
    for s, t in missing:
        print(f'  {s} -> {t}')
else:
    print(f'All {len(all_links)} inter-page links resolve correctly.')
"

